import shutil
from pathlib import Path

PATH = Path(
    r".\src\lupix_studio\ui\area2d_component_editor.py"
)

if not PATH.exists():
    raise FileNotFoundError(
        f"Arquivo não encontrado: {PATH}"
    )

backup = PATH.with_suffix(
    PATH.suffix + ".bak_actions_editor"
)

if not backup.exists():
    shutil.copy2(
        PATH,
        backup,
    )

content = 'from __future__ import annotations\n\nfrom pathlib import Path\n\nfrom PySide6.QtCore import Signal\nfrom PySide6.QtWidgets import (\n    QCheckBox,\n    QComboBox,\n    QDoubleSpinBox,\n    QFormLayout,\n    QHBoxLayout,\n    QLabel,\n    QLineEdit,\n    QPushButton,\n    QScrollArea,\n    QVBoxLayout,\n    QWidget,\n)\n\nfrom lupix_studio.scene.model import (\n    Area2DAction,\n    Area2DComponent,\n    SceneEntity,\n    SceneResource,\n)\n\n\nclass Area2DComponentEditor(QWidget):\n    """Editor do componente Area2D."""\n\n    area2d_changed = Signal(str)\n\n    def __init__(self) -> None:\n        super().__init__()\n\n        self.project_root: Path | None = None\n        self.scene: SceneResource | None = None\n        self.entity: SceneEntity | None = None\n        self._updating = False\n\n        self.status_label = QLabel(\n            "Nenhuma entidade selecionada."\n        )\n        self.status_label.setWordWrap(True)\n\n        self.add_button = QPushButton(\n            "Adicionar Area2D"\n        )\n\n        self.enabled_checkbox = QCheckBox(\n            "Ativa"\n        )\n        self.detect_player_checkbox = QCheckBox(\n            "Detectar Player"\n        )\n        self.debug_visible_checkbox = QCheckBox(\n            "Mostrar área no editor"\n        )\n\n        self.width_spin = self._size_spin(64.0)\n        self.height_spin = self._size_spin(64.0)\n        self.offset_x_spin = self._offset_spin()\n        self.offset_y_spin = self._offset_spin()\n\n        size_form = QFormLayout()\n        size_form.addRow(\n            "Largura:",\n            self.width_spin,\n        )\n        size_form.addRow(\n            "Altura:",\n            self.height_spin,\n        )\n        size_form.addRow(\n            "Offset X:",\n            self.offset_x_spin,\n        )\n        size_form.addRow(\n            "Offset Y:",\n            self.offset_y_spin,\n        )\n\n        self.events_title = QLabel(\n            "Ao entrar"\n        )\n        self.events_title.setStyleSheet(\n            "font-weight: 600; margin-top: 8px;"\n        )\n\n        self.trigger_once_checkbox = QCheckBox(\n            "Executar apenas uma vez"\n        )\n\n        self.actions_widget = QWidget()\n        self.actions_layout = QVBoxLayout(\n            self.actions_widget\n        )\n        self.actions_layout.setContentsMargins(\n            0,\n            0,\n            0,\n            0,\n        )\n        self.actions_layout.setSpacing(6)\n\n        self.actions_scroll = QScrollArea()\n        self.actions_scroll.setWidgetResizable(True)\n        self.actions_scroll.setMinimumHeight(170)\n        self.actions_scroll.setWidget(\n            self.actions_widget\n        )\n\n        self.add_action_button = QPushButton(\n            "+ Adicionar ação"\n        )\n\n        self.hint_label = QLabel(\n            "As ações são executadas de cima para baixo."\n        )\n        self.hint_label.setWordWrap(True)\n\n        self.remove_button = QPushButton(\n            "Remover Area2D"\n        )\n\n        layout = QVBoxLayout(self)\n        layout.setContentsMargins(\n            0,\n            0,\n            0,\n            0,\n        )\n        layout.setSpacing(8)\n        layout.addWidget(self.status_label)\n        layout.addWidget(self.add_button)\n        layout.addWidget(self.enabled_checkbox)\n        layout.addLayout(size_form)\n        layout.addWidget(\n            self.detect_player_checkbox\n        )\n        layout.addWidget(\n            self.debug_visible_checkbox\n        )\n        layout.addWidget(self.events_title)\n        layout.addWidget(\n            self.trigger_once_checkbox\n        )\n        layout.addWidget(self.actions_scroll)\n        layout.addWidget(\n            self.add_action_button\n        )\n        layout.addWidget(self.hint_label)\n        layout.addWidget(self.remove_button)\n        layout.addStretch()\n\n        self.add_button.clicked.connect(\n            self._add_area2d\n        )\n        self.remove_button.clicked.connect(\n            self._remove_area2d\n        )\n        self.add_action_button.clicked.connect(\n            self._add_action\n        )\n\n        for control in (\n            self.enabled_checkbox,\n            self.detect_player_checkbox,\n            self.debug_visible_checkbox,\n            self.trigger_once_checkbox,\n        ):\n            control.toggled.connect(\n                self._apply\n            )\n\n        for spin in (\n            self.width_spin,\n            self.height_spin,\n            self.offset_x_spin,\n            self.offset_y_spin,\n        ):\n            spin.valueChanged.connect(\n                self._apply\n            )\n\n        self.set_context(\n            None,\n            None,\n            None,\n        )\n\n    @staticmethod\n    def _size_spin(\n        value: float,\n    ) -> QDoubleSpinBox:\n        spin = QDoubleSpinBox()\n        spin.setRange(\n            1.0,\n            100000.0,\n        )\n        spin.setDecimals(1)\n        spin.setValue(value)\n        return spin\n\n    @staticmethod\n    def _offset_spin() -> QDoubleSpinBox:\n        spin = QDoubleSpinBox()\n        spin.setRange(\n            -100000.0,\n            100000.0,\n        )\n        spin.setDecimals(1)\n        return spin\n\n    def set_context(\n        self,\n        scene: SceneResource | None,\n        entity: SceneEntity | None,\n        project_root: Path | None = None,\n    ) -> None:\n        self.scene = scene\n        self.entity = entity\n\n        if project_root is not None:\n            self.project_root = Path(\n                project_root\n            ).resolve()\n        elif scene is None:\n            self.project_root = None\n\n        self._refresh()\n\n    def refresh_scene_list(self) -> None:\n        self._refresh_actions()\n\n    def _refresh(self) -> None:\n        self._updating = True\n\n        try:\n            if self.entity is None:\n                self.status_label.setText(\n                    "Nenhuma entidade selecionada."\n                )\n                self.add_button.setVisible(False)\n                self._set_controls_visible(False)\n                return\n\n            area = self.entity.area2d\n\n            if area is None:\n                self.status_label.setText(\n                    "Esta entidade ainda não possui Area2D."\n                )\n                self.add_button.setVisible(True)\n                self._set_controls_visible(False)\n                return\n\n            self.status_label.setText(\n                "Area2D anexada a esta entidade."\n            )\n            self.add_button.setVisible(False)\n            self._set_controls_visible(True)\n\n            self.enabled_checkbox.setChecked(\n                area.enabled\n            )\n            self.width_spin.setValue(\n                area.width\n            )\n            self.height_spin.setValue(\n                area.height\n            )\n            self.offset_x_spin.setValue(\n                area.offset_x\n            )\n            self.offset_y_spin.setValue(\n                area.offset_y\n            )\n            self.detect_player_checkbox.setChecked(\n                area.detect_player\n            )\n            self.debug_visible_checkbox.setChecked(\n                area.debug_visible\n            )\n            self.trigger_once_checkbox.setChecked(\n                area.trigger_once\n            )\n\n            self._refresh_actions()\n\n        finally:\n            self._updating = False\n\n    def _set_controls_visible(\n        self,\n        visible: bool,\n    ) -> None:\n        for widget in (\n            self.enabled_checkbox,\n            self.width_spin,\n            self.height_spin,\n            self.offset_x_spin,\n            self.offset_y_spin,\n            self.detect_player_checkbox,\n            self.debug_visible_checkbox,\n            self.events_title,\n            self.trigger_once_checkbox,\n            self.actions_scroll,\n            self.add_action_button,\n            self.hint_label,\n            self.remove_button,\n        ):\n            widget.setVisible(visible)\n\n    def _clear_actions_ui(self) -> None:\n        while self.actions_layout.count():\n            item = self.actions_layout.takeAt(0)\n            widget = item.widget()\n\n            if widget is not None:\n                widget.deleteLater()\n\n    def _refresh_actions(self) -> None:\n        self._clear_actions_ui()\n\n        if (\n            self.entity is None\n            or self.entity.area2d is None\n        ):\n            return\n\n        actions = (\n            self.entity.area2d.on_enter_actions\n        )\n\n        if not actions:\n            empty = QLabel(\n                "Nenhuma ação configurada."\n            )\n            empty.setWordWrap(True)\n            self.actions_layout.addWidget(\n                empty\n            )\n            return\n\n        for index, action in enumerate(actions):\n            row = self._build_action_row(\n                index,\n                action,\n            )\n            self.actions_layout.addWidget(\n                row\n            )\n\n        self.actions_layout.addStretch()\n\n    def _build_action_row(\n        self,\n        index: int,\n        action: Area2DAction,\n    ) -> QWidget:\n        container = QWidget()\n        outer = QVBoxLayout(container)\n        outer.setContentsMargins(\n            6,\n            6,\n            6,\n            6,\n        )\n        outer.setSpacing(5)\n\n        header = QHBoxLayout()\n\n        number = QLabel(\n            f"{index + 1}."\n        )\n\n        action_combo = QComboBox()\n        action_combo.addItem(\n            "Mostrar mensagem",\n            "show_message",\n        )\n        action_combo.addItem(\n            "Aguardar",\n            "wait",\n        )\n        action_combo.addItem(\n            "Trocar cena",\n            "change_scene",\n        )\n\n        selected = action_combo.findData(\n            action.action\n        )\n        action_combo.setCurrentIndex(\n            max(\n                0,\n                selected,\n            )\n        )\n\n        up_button = QPushButton("↑")\n        down_button = QPushButton("↓")\n        remove_button = QPushButton("×")\n\n        for button in (\n            up_button,\n            down_button,\n            remove_button,\n        ):\n            button.setFixedWidth(30)\n\n        up_button.setEnabled(\n            index > 0\n        )\n        down_button.setEnabled(\n            index\n            < len(\n                self.entity.area2d.on_enter_actions\n            )\n            - 1\n        )\n\n        header.addWidget(number)\n        header.addWidget(\n            action_combo,\n            1,\n        )\n        header.addWidget(up_button)\n        header.addWidget(down_button)\n        header.addWidget(remove_button)\n\n        outer.addLayout(header)\n\n        details = QWidget()\n        details_layout = QFormLayout(\n            details\n        )\n        details_layout.setContentsMargins(\n            24,\n            0,\n            0,\n            0,\n        )\n\n        message_edit = QLineEdit()\n        message_edit.setPlaceholderText(\n            "Texto exibido ao jogador..."\n        )\n        message_edit.setText(\n            action.message_text\n        )\n\n        wait_spin = QDoubleSpinBox()\n        wait_spin.setRange(\n            0.0,\n            3600.0,\n        )\n        wait_spin.setDecimals(2)\n        wait_spin.setSingleStep(0.25)\n        wait_spin.setSuffix(" s")\n        wait_spin.setValue(\n            action.wait_seconds\n        )\n\n        scene_combo = QComboBox()\n        scene_combo.setMinimumWidth(180)\n        self._populate_scene_combo(\n            scene_combo,\n            action.target_scene,\n        )\n\n        details_layout.addRow(\n            "Mensagem:",\n            message_edit,\n        )\n        details_layout.addRow(\n            "Tempo:",\n            wait_spin,\n        )\n        details_layout.addRow(\n            "Cena destino:",\n            scene_combo,\n        )\n\n        outer.addWidget(details)\n\n        def update_details() -> None:\n            kind = str(\n                action_combo.currentData()\n                or ""\n            )\n\n            message_edit.setVisible(\n                kind == "show_message"\n            )\n            details_layout.labelForField(\n                message_edit\n            ).setVisible(\n                kind == "show_message"\n            )\n\n            wait_spin.setVisible(\n                kind == "wait"\n            )\n            details_layout.labelForField(\n                wait_spin\n            ).setVisible(\n                kind == "wait"\n            )\n\n            scene_combo.setVisible(\n                kind == "change_scene"\n            )\n            details_layout.labelForField(\n                scene_combo\n            ).setVisible(\n                kind == "change_scene"\n            )\n\n        def save_row() -> None:\n            if self._updating:\n                return\n\n            if (\n                self.entity is None\n                or self.entity.area2d is None\n            ):\n                return\n\n            if index >= len(\n                self.entity.area2d.on_enter_actions\n            ):\n                return\n\n            current = (\n                self.entity.area2d.on_enter_actions[\n                    index\n                ]\n            )\n\n            current.action = str(\n                action_combo.currentData()\n                or "none"\n            )\n            current.message_text = (\n                message_edit.text()\n            )\n            current.wait_seconds = (\n                wait_spin.value()\n            )\n            current.target_scene = str(\n                scene_combo.currentData()\n                or ""\n            )\n\n            update_details()\n            self._sync_legacy_fields()\n            self.area2d_changed.emit(\n                self.entity.id\n            )\n\n        action_combo.currentIndexChanged.connect(\n            save_row\n        )\n        message_edit.textChanged.connect(\n            save_row\n        )\n        wait_spin.valueChanged.connect(\n            save_row\n        )\n        scene_combo.currentIndexChanged.connect(\n            save_row\n        )\n\n        up_button.clicked.connect(\n            lambda: self._move_action(\n                index,\n                -1,\n            )\n        )\n        down_button.clicked.connect(\n            lambda: self._move_action(\n                index,\n                1,\n            )\n        )\n        remove_button.clicked.connect(\n            lambda: self._remove_action(\n                index\n            )\n        )\n\n        update_details()\n\n        return container\n\n    def _populate_scene_combo(\n        self,\n        combo: QComboBox,\n        selected_path: str = "",\n    ) -> None:\n        combo.clear()\n        combo.addItem(\n            "Selecione uma cena...",\n            "",\n        )\n\n        if self.project_root is None:\n            return\n\n        scenes_dir = (\n            self.project_root\n            / "scenes"\n        )\n\n        if not scenes_dir.exists():\n            return\n\n        scene_files = sorted(\n            scenes_dir.rglob("*.scene"),\n            key=lambda path: str(\n                path.relative_to(\n                    scenes_dir\n                )\n            ).lower(),\n        )\n\n        normalized_selected = (\n            selected_path.replace(\n                "\\\\",\n                "/",\n            )\n        )\n\n        selected_index = 0\n\n        for scene_path in scene_files:\n            relative_project = (\n                scene_path.relative_to(\n                    self.project_root\n                )\n            )\n\n            stored_path = (\n                relative_project.as_posix()\n            )\n\n            display_name = (\n                scene_path.relative_to(\n                    scenes_dir\n                )\n                .with_suffix("")\n                .as_posix()\n            )\n\n            combo.addItem(\n                display_name,\n                stored_path,\n            )\n\n            if (\n                stored_path\n                == normalized_selected\n            ):\n                selected_index = (\n                    combo.count()\n                    - 1\n                )\n\n        combo.setCurrentIndex(\n            selected_index\n        )\n\n    def _add_action(self) -> None:\n        if (\n            self.entity is None\n            or self.entity.area2d is None\n        ):\n            return\n\n        self.entity.area2d.on_enter_actions.append(\n            Area2DAction(\n                action="show_message"\n            )\n        )\n\n        self._sync_legacy_fields()\n        self._refresh_actions()\n\n        self.area2d_changed.emit(\n            self.entity.id\n        )\n\n    def _remove_action(\n        self,\n        index: int,\n    ) -> None:\n        if (\n            self.entity is None\n            or self.entity.area2d is None\n        ):\n            return\n\n        actions = (\n            self.entity.area2d.on_enter_actions\n        )\n\n        if not (\n            0 <= index < len(actions)\n        ):\n            return\n\n        actions.pop(index)\n\n        self._sync_legacy_fields()\n        self._refresh_actions()\n\n        self.area2d_changed.emit(\n            self.entity.id\n        )\n\n    def _move_action(\n        self,\n        index: int,\n        direction: int,\n    ) -> None:\n        if (\n            self.entity is None\n            or self.entity.area2d is None\n        ):\n            return\n\n        actions = (\n            self.entity.area2d.on_enter_actions\n        )\n\n        target = index + direction\n\n        if not (\n            0 <= index < len(actions)\n            and 0 <= target < len(actions)\n        ):\n            return\n\n        actions[index], actions[target] = (\n            actions[target],\n            actions[index],\n        )\n\n        self._sync_legacy_fields()\n        self._refresh_actions()\n\n        self.area2d_changed.emit(\n            self.entity.id\n        )\n\n    def _sync_legacy_fields(self) -> None:\n        if (\n            self.entity is None\n            or self.entity.area2d is None\n        ):\n            return\n\n        area = self.entity.area2d\n\n        area.on_enter_action = "none"\n        area.target_scene = ""\n        area.message_text = ""\n\n        actions = area.on_enter_actions\n\n        if len(actions) == 1:\n            action = actions[0]\n\n            area.on_enter_action = (\n                action.action\n            )\n            area.target_scene = (\n                action.target_scene\n            )\n            area.message_text = (\n                action.message_text\n            )\n            return\n\n        if (\n            len(actions) == 3\n            and actions[0].action\n            == "show_message"\n            and actions[1].action\n            == "wait"\n            and actions[2].action\n            == "change_scene"\n        ):\n            area.on_enter_action = (\n                "message_change_scene"\n            )\n            area.message_text = (\n                actions[0].message_text\n            )\n            area.target_scene = (\n                actions[2].target_scene\n            )\n\n    def _add_area2d(self) -> None:\n        if self.entity is None:\n            return\n\n        if self.entity.area2d is not None:\n            return\n\n        self.entity.area2d = (\n            Area2DComponent()\n        )\n        self.entity.refresh_kind()\n        self._refresh()\n\n        self.area2d_changed.emit(\n            self.entity.id\n        )\n\n    def _remove_area2d(self) -> None:\n        if self.entity is None:\n            return\n\n        self.entity.area2d = None\n        self.entity.refresh_kind()\n        self._refresh()\n\n        self.area2d_changed.emit(\n            self.entity.id\n        )\n\n    def _apply(self) -> None:\n        if self._updating:\n            return\n\n        if (\n            self.entity is None\n            or self.entity.area2d is None\n        ):\n            return\n\n        area = self.entity.area2d\n\n        area.enabled = (\n            self.enabled_checkbox.isChecked()\n        )\n        area.width = max(\n            1.0,\n            self.width_spin.value(),\n        )\n        area.height = max(\n            1.0,\n            self.height_spin.value(),\n        )\n        area.offset_x = (\n            self.offset_x_spin.value()\n        )\n        area.offset_y = (\n            self.offset_y_spin.value()\n        )\n        area.detect_player = (\n            self.detect_player_checkbox.isChecked()\n        )\n        area.debug_visible = (\n            self.debug_visible_checkbox.isChecked()\n        )\n        area.trigger_once = (\n            self.trigger_once_checkbox.isChecked()\n        )\n\n        self._sync_legacy_fields()\n\n        self.area2d_changed.emit(\n            self.entity.id\n        )\n'

PATH.write_text(
    content,
    encoding="utf-8",
)

print("Inspector Area2D atualizado.")
print("Agora ele suporta:")
print("  + Adicionar ação")
print("  - Mostrar mensagem")
print("  - Aguardar")
print("  - Trocar cena")
print("  - Reordenar com ↑ e ↓")
print("  - Remover ação")
print("  - Executar apenas uma vez")
print()
print(f"Backup: {backup}")
